}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group gutenify-section-e7c561b0-7de5-11ef-82f7-e53f9fd7b5c7\" style=\"padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:0px\"><!-- wp:paragraph {\"align\":\"left\",\"blockClientId\":\"e7c11bf0-7de5-11ef-82f7-e53f9fd7b5c7\",\"style\":{\"typography\":{\"letterSpacing\":\"4px\"}},\"textColor\":\"primary\",\"className\":\" animated animated-fadeInUp\"} -->\n<p class=\"has-text-align-left animated animated-fadeInUp has-primary-color has-text-color gutenify-section-e7c11bf0-7de5-11ef-82f7-e53f9fd7b5c7\" style=\"letter-spacing:4px\">Obtén tu producto o servicio</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"textAlign\":\"left\",\"blockClientId\":\"e7c38cf0-7de5-11ef-82f7-e53f9fd7b5c7\",\"style\":{\"spacing\":{\"margin\":{\"bottom\":\"0px\"}}},\"className\":\" animated animated-fadeInUp\",\"fontSize\":\"large\"} -->\n<h2 class=\"wp-block-heading has-text-align-left animated animated-fadeInUp has-large-font-size gutenify-section-e7c38cf0-7de5-11ef-82f7-e53f9fd7b5c7\" style=\"margin-bottom:0px\">Productos y Servicios Model Bolivia </h2>\n<!-- /wp:heading --></div>\n<!-- /wp:group -->\n\n<!-- wp:buttons {\"blockClientId\":\"e7ca43b0-7de5-11ef-82f7-e53f9fd7b5c7\",\"className\":\" animated animated-fadeInUp\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"left\"},\"style\":{\"spacing\":{\"blockGap\":\"10px\",\"margin\":{\"top\":\"20px\",\"bottom\":\"20px\"}}}} -->\n<div class=\"wp-block-buttons animated animated-fadeInUp gutenify-section-e7ca43b0-7de5-11ef-82f7-e53f9fd7b5c7\" style=\"margin-top:20px;margin-bottom:20px\"><!-- wp:button {\"blockClientId\":\"e7c847e0-7de5-11ef-82f7-e53f9fd7b5c7\",\"style\":{\"border\":{\"radius\":\"0px\"},\"spacing\":{\"padding\":{\"right\":\"35px\",\"left\":\"35px\"}}},\"className\":\"is-style-fill\"} -->\n<div class=\"wp-block-button is-style-fill gutenify-section-e7c847e0-7de5-11ef-82f7-e53f9fd7b5c7\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://modelbolivia.github.io/administracion/about.html\" style=\"border-radius:0px;padding-right:35px;padding-left:35px\">Mas Información</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"gutenify-business-dark\",\"tagName\":\"footer\",\"blockClientId\":\"d833f040-7de5-11ef-82f7-e53f9fd7b5c7\"} /-->','Inicio del blog','Muestra las entradas más recientes, así como la página de inicio del sitio o una página personalizada definida en los ajustes de lectura. Si existe, la plantilla de página de inicio sobreescribirá a esta plantilla cuando se muestren las entradas en dicha página de inicio.','inherit','closed','closed','','8-revision-v1','','','2024-10-08 00:09:48','2024-10-08 00:09:48','','8','http://localhost/dinamica_suerte_virtual_base/?p=59','0','revision','','0');
INSERT INTO `SERVMASK_PREFIX_posts` VALUES ('60','1','2024-10-08 00:16:37','2024-10-08 00:16:37','<!-- wp:template-part {\"slug\":\"header\",\"theme\":\"gutenify-business-dark\",\"tagName\":\"header\",\"blockClientId\":\"d82682c0-7de5-11ef-82f7-e53f9fd7b5c7\"} /-->\n\n<!-- wp:cover {\"url\":\"http://localhost/dinamica_suerte_virtual_base/wp-content/themes/gutenify-business-dark/images/main-banner.jpg\",\"id\":2561,\"dimRatio\":50,\"focalPoint\":{\"x\":\"0.74\",\"y\":\"0.40\"},\"minHeight\":700,\"customGradient\":\"linear-gradient(90deg,rgb(0,0,0) 42%,rgba(0,0,0,0.22) 77%)\",\"blockClientId\":\"e75588e0-7de5-11ef-82f7-e53f9fd7b5c7\",\"align\":\"full\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"150px\",\"right\":\"30px\",\"bottom\":\"150px\",\"left\":\"30px\"}}}} -->\n<div class=\"wp-block-cover alignfull gutenify-section-e75588e0-7de5-11ef-82f7-e53f9fd7b5c7\" style=\"padding-top:150px;padding-right:30px;padding-bottom:150px;padding-left:30px;min-height:700px\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim wp-block-cover__gradient-background has-background-gradient\" style=\"background:linear-gradient(90deg,rgb(0,0,0) 42%,rgba(0,0,0,0.22) 77%)\"></span><img class=\"wp-block-cover__image-background wp-image-2561\" alt=\"\" src=\"http://localhost/dinamica_suerte_virtual_base/wp-content/themes/gutenify-business-dark/images/main-banner.jpg\" style=\"object-position:74% 40%\" data-object-fit=\"cover\" data-object-position=\"74% 40%\"/><div class=\"wp-block-cover__inner-container\"><!-- wp:group {\"blockClientId\":\"e7525490-7de5-11ef-82f7-e53f9fd7b5c7\",\"align\":\"wide\",\"style\":{\"spacing\":{\"padding\":{\"left\":\"10%\"}}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group alignwide gutenify-section-e7525490-7de5-11ef-82f7-e53f9fd7b5c7\" style=\"padding-left:10%\"><!-- wp:group {\"blockClientId\":\"e74f4750-7de5-11ef-82f7-e53f9fd7b5c7\",\"align\":\"wide\",\"style\":{\"spacing\":{\"blockGap\":\"0px\",\"padding\":{\"top\":\"0px\",\"right\":\"0px\",\"bottom\":\"0px\",\"left\":\"0px\"}}},\"layout\":{\"inherit\":false}} -->\n<div class=\"wp-block-group alignwide gutenify-section-e74f4750-7de5-11ef-82f7-e53f9fd7b5c7\" style=\"padding-top:0px;padding-right:0px;padding-bottom:0px;padding-left:0px\"><!-- wp:heading {\"level\":3,\"blockClientId\":\"e7427610-7de5-11ef-82f7-e53f9fd7b5c7\",\"style\":{\"typography\":{\"lineHeight\":\"1.5\",\"letterSpacing\":\"3px\"}},\"textColor\":\"primary\",\"className\":\" animated animated-fadeInUp\"} -->\n<h3 class=\"wp-block-heading animated animated-fadeInUp has-primary-color has-text-color gutenify-section-e7427610-7de5-11ef-82f7-e53f9fd7b5c7\" style=\"letter-spacing:3px;line-height:1.5\">Juega esta Dinámica</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"blockClientId\":\"e743fcb0-7de5-11ef-82f7-e53f9fd7b5c7\",\"style\":{\"typography\":{\"fontStyle\":\"normal\",\"fontWeight\":\"900\",\"lineHeight\":\"1.5\"}},\"textColor\":\"light\",\"className\":\"animated fadeInUp\",\"fontSize\":\"gigantic\"} -->\n<h2 class=\"wp-block-heading animated fadeInUp has-light-color has-text-color has-gigantic-font-size gutenify-section-e743fcb0-7de5-11ef-82f7-e53f9fd7b5c7\" style=\"font-style:normal;font-weight:900;line-height:1.5\">Dinámica de Suerte Virtual</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"blockClientId\":\"1bca73a0-8508-11ef-8b49-3f6b26196db1\"} -->\n<p class=\"gutenify-section-1bca73a0-8508-11ef-8b49-3f6b26196db1\">Prueba y obtiene el numero ganador.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"blockClientId\":\"e745aa60-7de5-11ef-82f7-e53f9fd7b5c7\",\"textColor\":\"background\",\"className\":\" animated animated-fadeInUp\"} -->\n<p class=\" animated animated-fadeInUp has-background-color has-text-color gutenify-section-e745aa60-7de5-11ef-82f7-e53f9fd7b5c7\" id=\"block-ffd2f2b6-a569-45d4-b7b0-b72408e7aa8e\">Obtén tu ticket para ganarlo, o bien adquiere uno de nuestros artículos así cada viernes tendrás oportunidad de ganar.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"blockClientId\":\"e7477f20-7de5-11ef-82f7-e53f9fd7b5c7\",\"textColor\":\"background\",\"className\":\" animated animated-fadeInUp\"} -->\n<p class=\" animated animated-fadeInUp has-background-color has-text-color gutenify-section-e7477f20-7de5-11ef-82f7-e53f9fd7b5c7\" id=\"block-3fb46f4e-572b-497d-9d61-c0ab532ce2a0\">Cada vez que participes con un ticket tendrás oportunidad de ser parte de la promoción del mes.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {\"blockClientId\":\"e74cd650-7de5-11ef-82f7-e53f9fd7b5c7\",\"className\":\" animated animated-fadeInUp\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"left\"},\"style\":{\"spacing\":{\"margin\":{\"top\":\"40px\",\"bottom\":\"20px\"}}}} -->\n<div class=\"wp-block-buttons animated animated-fadeInUp gutenify-section-e74cd650-7de5-11ef-82f7-e53f9fd7b5c7\" style=\"margin-top:40px;margin-bottom:20px\"><!-- wp:button {\"backgroundColor\":\"primary\",\"textColor\":\"background\",\"blockClientId\":\"e74953e0-7de5-11ef-82f7-e53f9fd7b5c7\",\"style\":{\"border\":{\"radius\":\"0px\"},\"spacing\":{\"padding\":{\"right\":\"35px\",\"left\":\"35px\"}}},\"className\":\"is-style-fill\"} -->\n<div class=\"wp-block-button is-style-fill gutenify-section-e74953e0-7de5-11ef-82f7-e53f9fd7b5c7\"><a class=\"wp-block-button__link has-background-color has-primary-background-color has-text-color has-background wp-element-button\" href=\"#\" style=\"border-radius:0px;padding-right:35px;padding-left:35px\">Juega </a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {\"textColor\":\"background\",\"blockClientId\":\"e74b28a0-7de5-11ef-82f7-e53f9fd7b5c7\",\"style\":{\"border\":{\"radius\":\"0px\"},\"spacing\":{\"padding\":{\"right\":\"35px\",\"left\":\"35px\",\"top\":\"8px\",\"bottom\":\"8px\"}}},\"className\":\"is-style-outline\"} -->\n<div class=\"wp-block-button is-style-outline gutenify-section-e74b28a0-7de5-11ef-82f7-e53f9fd7b5c7\"><a class=\"wp-block-button__link has-background-color has-text-color wp-element-button\" href=\"#\" style=\"border-radius:0px;padding-top:8px;padding-right:35px;padding-bottom:8px;padding-left:35px\">Mas información</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:pattern {\"slug\":\"gutenify-business-dark/service-one\",\"blockClientId\":\"d82a2c40-7de5-11ef-82f7-e53f9fd7b5c7\"} /-->\n\n<!-- wp:group {\"blockClientId\":\"e782da70-7de5-11ef-82f7-e53f9fd7b5c7\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"80px\",\"bottom\":\"80px\"}},\"color\":{\"background\":\"#111111\"}},\"layout\":{\"inherit\":true,\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-background gutenify-section-e782da70-7de5-11ef-82f7-e53f9fd7b5c7\" style=\"background-color:#111111;padding-top:80px;padding-bottom:80px\"><!-- wp:columns {\"blockClientId\":\"e77ff440-7de5-11ef-82f7-e53f9fd7b5c7\",\"align\":\"wide\"} -->\n<div class=\"wp-block-columns alignwide gutenify-section-e77ff440-7de5-11ef-82f7-e53f9fd7b5c7\"><!-- wp:column {\"blockClientId\":\"e76f7980-7de5-11ef-82f7-e53f9fd7b5c7\"} -->\n<div class=\"wp-block-column gutenify-section-e76f7980-7de5-11ef-82f7-e53f9fd7b5c7\"><!-- wp:image {\"id\":2891,\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"blockClientId\":\"e76dcbd0-7de5-11ef-82f7-e53f9fd7b5c7\",\"className\":\" animated animated-fadeInUp\"} -->\n<figure class=\"wp-block-image size-large  animated animated-fadeInUp gutenify-section-e76dcbd0-7de5-11ef-82f7-e53f9fd7b5c7\"><img src=\"http://localhost/dinamica_suerte_virtual_base/wp-content/themes/gutenify-business-dark/images/hero-image.png\" alt=\"\" class=\"wp-image-2891\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"verticalAlignment\":\"center\",\"blockClientId\":\"e77dd160-7de5-11ef-82f7-e53f9fd7b5c7\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"40px\",\"right\":\"40px\",\"bottom\":\"40px\",\"left\":\"40px\"}}}} -->\n<div class