wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"blockClientId\":\"4694e200-8e68-11ef-8d43-1563d6feca97\",\"className\":\"gutenify-admin-info-box-block-content\"} -->\n<p class=\"has-text-align-center gutenify-admin-info-box-block-content gutenify-section-4694e200-8e68-11ef-8d43-1563d6feca97\">Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed sit amet est massa. Sed enim massa, mattis at libero nec, bibendum ultricies augue.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:gutenify/buttons {\"blockClientId\":\"46961a80-8e68-11ef-8d43-1563d6feca97\",\"contentJustification\":\"center\"} -->\n<div class=\"wp-block-gutenify-buttons is-content-justification-center wp-block-buttons gutenify-buttons-version-2 gutenify-section-46961a80-8e68-11ef-8d43-1563d6feca97\"><!-- wp:gutenify/button {\"blockClientId\":\"46eb3f60-8e68-11ef-8d43-1563d6feca97\"} /--></div>\n<!-- /wp:gutenify/buttons --></div>\n<!-- /wp:gutenify/info-box --></div></div>\n<!-- /wp:gutenify/service -->\n\n<!-- wp:columns {\"blockClientId\":\"5f75bfb0-8e68-11ef-8d43-1563d6feca97\"} -->\n<div class=\"wp-block-columns gutenify-section-5f75bfb0-8e68-11ef-8d43-1563d6feca97\"><!-- wp:column {\"width\":\"100%\",\"blockClientId\":\"5f70b6a0-8e68-11ef-8d43-1563d6feca97\"} -->\n<div class=\"wp-block-column gutenify-section-5f70b6a0-8e68-11ef-8d43-1563d6feca97\" style=\"flex-basis:100%\"><!-- wp:cover {\"url\":\"http://localhost/dinamica_suerte_virtual_base/wp-content/uploads/2024/09/Participa-en-enventos-1-1.jpg\",\"id\":18,\"dimRatio\":50,\"customOverlayColor\":\"#a99c99\",\"isDark\":false,\"blockClientId\":\"6dc31860-8e68-11ef-8d43-1563d6feca97\"} -->\n<div class=\"wp-block-cover is-light gutenify-section-6dc31860-8e68-11ef-8d43-1563d6feca97\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\" style=\"background-color:#a99c99\"></span><img class=\"wp-block-cover__image-background wp-image-18\" alt=\"\" src=\"http://localhost/dinamica_suerte_virtual_base/wp-content/uploads/2024/09/Participa-en-enventos-1-1.jpg\" data-object-fit=\"cover\"/><div class=\"wp-block-cover__inner-container\"><!-- wp:group {\"blockClientId\":\"68cfb340-8e68-11ef-8d43-1563d6feca97\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group gutenify-section-68cfb340-8e68-11ef-8d43-1563d6feca97\"><!-- wp:gutenify/advance-slider {\"blockClientId\":\"548fade0-8e68-11ef-8d43-1563d6feca97\"} -->\n<!-- wp:gutenify/advance-slide-item {\"blockClientId\":\"5508ae70-8e68-11ef-8d43-1563d6feca97\"} -->\n<div class=\"wp-block-gutenify-advance-slide-item gutenify-block-slide-item-wrapper swiper-slide gutenify-advance-slide-item-version-2 gutenify-section-5508ae70-8e68-11ef-8d43-1563d6feca97\"><!-- wp:cover {\"dimRatio\":50,\"isDark\":false,\"blockClientId\":\"55521380-8e68-11ef-8d43-1563d6feca97\"} -->\n<div class=\"wp-block-cover is-light gutenify-section-55521380-8e68-11ef-8d43-1563d6feca97\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"center\",\"placeholder\":\"Slider Content Here.\",\"blockClientId\":\"555017b0-8e68-11ef-8d43-1563d6feca97\",\"style\":{\"color\":{\"text\":\"#272525\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center has-text-color gutenify-section-555017b0-8e68-11ef-8d43-1563d6feca97\" style=\"color:#272525\"><img class=\"wp-image-18\" style=\"width: 150px;\" src=\"http://localhost/dinamica_suerte_virtual_base/wp-content/uploads/2024/09/Participa-en-enventos-1-1.jpg\" alt=\"\"></h2>\n<!-- /wp:heading --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:gutenify/advance-slide-item -->\n\n<!-- wp:gutenify/advance-slide-item {\"blockClientId\":\"550ad150-8e68-11ef-8d43-1563d6feca97\"} -->\n<div class=\"wp-block-gutenify-advance-slide-item gutenify-block-slide-item-wrapper swiper-slide gutenify-advance-slide-item-version-2 gutenify-section-550ad150-8e68-11ef-8d43-1563d6feca97\"><!-- wp:cover {\"useFeaturedImage\":true,\"dimRatio\":50,\"customOverlayColor\":\"#a99c99\",\"isDark\":false,\"blockClientId\":\"5555e410-8e68-11ef-8d43-1563d6feca97\"} -->\n<div class=\"wp-block-cover is-light gutenify-section-5555e410-8e68-11ef-8d43-1563d6feca97\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\" style=\"background-color:#a99c99\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"center\",\"placeholder\":\"Slider Content Here.\",\"blockClientId\":\"5553e840-8e68-11ef-8d43-1563d6feca97\",\"style\":{\"color\":{\"text\":\"#272525\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center has-text-color gutenify-section-5553e840-8e68-11ef-8d43-1563d6feca97\" style=\"color:#272525\"><img class=\"wp-image-48\" style=\"width: 150px;\" src=\"http://localhost/dinamica_suerte_virtual_base/wp-content/uploads/2024/10/modelaje-para-eventos-.jpg\" alt=\"\"></h2>\n<!-- /wp:heading --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:gutenify/advance-slide-item -->\n\n<!-- wp:gutenify/advance-slide-item {\"blockClientId\":\"638d91e0-8e68-11ef-8d43-1563d6feca97\"} -->\n<div class=\"wp-block-gutenify-advance-slide-item gutenify-block-slide-item-wrapper swiper-slide gutenify-advance-slide-item-version-2 gutenify-section-638d91e0-8e68-11ef-8d43-1563d6feca97\"><!-- wp:cover {\"useFeaturedImage\":true,\"dimRatio\":50,\"customOverlayColor\":\"#a99c99\",\"isDark\":false,\"blockClientId\":\"639ea8e0-8e68-11ef-8d43-1563d6feca97\"} -->\n<div class=\"wp-block-cover is-light gutenify-section-639ea8e0-8e68-11ef-8d43-1563d6feca97\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\" style=\"background-color:#a99c99\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"center\",\"placeholder\":\"Slider Content Here.\",\"blockClientId\":\"639c8600-8e68-11ef-8d43-1563d6feca97\",\"style\":{\"color\":{\"text\":\"#272525\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center ha