->\n<div class=\"wp-block-gutenify-advance-slide-item gutenify-block-slide-item-wrapper swiper-slide gutenify-advance-slide-item-version-2 gutenify-section-65e1bb10-8e68-11ef-8d43-1563d6feca97\"><!-- wp:cover {\"useFeaturedImage\":true,\"dimRatio\":50,\"customOverlayColor\":\"#a99c99\",\"isDark\":false,\"blockClientId\":\"65f47fc0-8e68-11ef-8d43-1563d6feca97\"} -->\n<div class=\"wp-block-cover is-light gutenify-section-65f47fc0-8e68-11ef-8d43-1563d6feca97\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\" style=\"background-color:#a99c99\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"center\",\"placeholder\":\"Slider Content Here.\",\"blockClientId\":\"65f283f0-8e68-11ef-8d43-1563d6feca97\",\"style\":{\"color\":{\"text\":\"#272525\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center has-text-color gutenify-section-65f283f0-8e68-11ef-8d43-1563d6feca97\" style=\"color:#272525\"><img class=\"wp-image-49\" style=\"width: 150px;\" src=\"http://localhost/dinamica_suerte_virtual_base/wp-content/uploads/2024/10/servicios-model-boivia-.jpg\" alt=\"\"></h2>\n<!-- /wp:heading --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:gutenify/advance-slide-item -->\n\n<!-- wp:gutenify/advance-slide-item {\"blockClientId\":\"66a13a80-8e68-11ef-8d43-1563d6feca97\"} -->\n<div class=\"wp-block-gutenify-advance-slide-item gutenify-block-slide-item-wrapper swiper-slide gutenify-advance-slide-item-version-2 gutenify-section-66a13a80-8e68-11ef-8d43-1563d6feca97\"><!-- wp:cover {\"useFeaturedImage\":true,\"dimRatio\":50,\"customOverlayColor\":\"#a99c99\",\"isDark\":false,\"blockClientId\":\"66b3ff30-8e68-11ef-8d43-1563d6feca97\"} -->\n<div class=\"wp-block-cover is-light gutenify-section-66b3ff30-8e68-11ef-8d43-1563d6feca97\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\" style=\"background-color:#a99c99\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"center\",\"placeholder\":\"Slider Content Here.\",\"blockClientId\":\"66b1dc50-8e68-11ef-8d43-1563d6feca97\",\"style\":{\"color\":{\"text\":\"#272525\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center has-text-color gutenify-section-66b1dc50-8e68-11ef-8d43-1563d6feca97\" style=\"color:#272525\"><img class=\"wp-image-51\" style=\"width: 150px;\" src=\"http://localhost/dinamica_suerte_virtual_base/wp-content/uploads/2024/10/Cartel-de-Cerveza-moderno-con-fotos-blanca-y-Negra-Poster.jpg\" alt=\"\"></h2>\n<!-- /wp:heading --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:gutenify/advance-slide-item -->\n\n<!-- wp:gutenify/advance-slide-item {\"blockClientId\":\"98c0cd50-8e68-11ef-8d43-1563d6feca97\"} -->\n<div class=\"wp-block-gutenify-advance-slide-item gutenify-block-slide-item-wrapper swiper-slide gutenify-advance-slide-item-version-2 gutenify-section-98c0cd50-8e68-11ef-8d43-1563d6feca97\"><!-- wp:cover {\"useFeaturedImage\":true,\"dimRatio\":50,\"customOverlayColor\":\"#a99c99\",\"isDark\":false,\"blockClientId\":\"98d67830-8e68-11ef-8d43-1563d6feca97\"} -->\n<div class=\"wp-block-cover is-light gutenify-section-98d67830-8e68-11ef-8d43-1563d6feca97\"><span aria-hidden=\"true\" class=\"wp-block-cover__background has-background-dim\" style=\"background-color:#a99c99\"></span><div class=\"wp-block-cover__inner-container\"><!-- wp:heading {\"textAlign\":\"center\",\"placeholder\":\"Slider Content Here.\",\"blockClientId\":\"98d3e020-8e68-11ef-8d43-1563d6feca97\",\"style\":{\"color\":{\"text\":\"#272525\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center has-text-color gutenify-section-98d3e020-8e68-11ef-8d43-1563d6feca97\" style=\"color:#272525\"><img class=\"wp-image-52\" style=\"width: 150px;\" src=\"http://localhost/dinamica_suerte_virtual_base/wp-content/uploads/2024/10/Publicidad-Model-Bolivia.jpg\" alt=\"\"></h2>\n<!-- /wp:heading -->\n\n<!-- wp:columns {\"blockClientId\":\"4f31d1b0-8e69-11ef-8d43-1563d6feca97\"} -->\n<div cla